"Hi, I'm Pip!":"¡Hola, soy Pip!",
"I'm a helper made by the Tenbright team using a computer, and my voice is made by a computer too.":"Soy un ayudante creado por el equipo de Tenbright con una computadora, y mi voz también la hace una computadora.",
"I collect light-beads.":"Colecciono cuentas de luz.",
"Ten beads make a lantern.":"Diez cuentas forman una linterna.",
"Will you help me light the Kingdom?":"¿Me ayudas a iluminar el Reino?",
"Hint":"Pista",
"Try again.":"Inténtalo otra vez.",
"Homeschool or not sure":"Educación en casa o no estoy seguro",
"How long we keep it":"Cuánto tiempo lo guardamos",
"How we use it":"Cómo lo usamos",
"How we'll know":"Cómo lo sabremos",
"Hundreds are the same, so look at the ones.":"Las centenas son iguales, así que mira las unidades.",
"I agree that Tenbright may keep my child's learning record on this device to choose their next activity and show me their progress.":"Acepto que Tenbright guarde el registro de aprendizaje de mi hijo en este dispositivo para elegir su próxima actividad y mostrarme su progreso.",
"I am this child's parent or legal guardian.":"Soy el padre, la madre o el tutor legal de este niño.",
"I found {N} lanterns you can already light.":"Encontré {N} linternas que ya puedes encender.",
"Now the map knows where to start.":"Ahora el mapa sabe dónde empezar.",
"I worked this out, but I made a mistake.":"Resolví esto, pero cometí un error.",
"Can you find it?":"¿Puedes encontrarlo?",
"I wrote it":"Ya lo escribí",
"If we change what we collect or how we use it, we will ask for your consent again before the change applies to your child.":"Si cambiamos lo que recopilamos o cómo lo usamos, le pediremos su consentimiento otra vez antes de aplicar el cambio a su hijo.",
"If you switch on voice answers on the grown-ups page, your child can tap the Talk button and say a number or a short command such as \"next\".":"Si activa las respuestas por voz en la página de adultos, su hijo puede tocar el botón Hablar y decir un número o una orden corta como \"siguiente\".",
"Speech is turned into text by your browser on this device; Tenbright uses it only if the browser can promise this happens on the device.":"El navegador convierte la voz en texto en este dispositivo; Tenbright la usa solo si el navegador puede garantizar que esto ocurre en el dispositivo.",
"The words are used once to read the answer and are then discarded.":"Las palabras se usan una vez para leer la respuesta y luego se descartan.",
"No audio and no transcript is recorded, kept or sent to us or anyone else.":"No se graba, guarda ni envía ningún audio ni transcripción, ni a nosotros ni a nadie.",
"The microphone is used only after a tap on Talk, for one short answer.":"El micrófono se usa solo después de tocar Hablar, para una respuesta corta.",
"Pip never asks your child to say their name or anything about themselves.":"Pip nunca le pide a su hijo que diga su nombre ni nada sobre sí mismo.",
"You can switch voice answers off at any time.":"Puede desactivar las respuestas por voz en cualquier momento.",
"In the full product this step will use an FTC-recognized method of verifiable parental consent.":"En el producto completo, este paso usará un método de consentimiento parental verificable reconocido por la FTC.",
"This preview records your agreement on this device only.":"Esta versión preliminar registra su aceptación solo en este dispositivo.",
"In this preview, everything stays in this browser on this device.":"En esta versión preliminar, todo se queda en este navegador, en este dispositivo.",
"Nothing is sent to us or to anyone else.":"No se envía nada a nosotros ni a nadie.",
"The app loads no outside fonts, analytics, ads or trackers.":"La aplicación no carga fuentes externas, analíticas, anuncios ni rastreadores.",
"Pip's voice is recorded audio made with an AI voice model and included in the app; if a sentence has no recording, a voice built into your device reads it.":"En inglés, la voz de Pip es audio grabado con un modelo de voz de IA e incluido en la aplicación; en los demás idiomas, o si una frase no tiene grabación, la lee una voz integrada en su dispositivo.",
"Speech recognition, if you turn it on, runs only on your device.":"El reconocimiento de voz, si lo activa, funciona solo en su dispositivo.",
