"Do they have the same number of digits?":"¿Tienen la misma cantidad de dígitos?",
"Compare from the biggest place to the smallest.":"Compara del lugar más grande al más pequeño.",
"Compare the populations of two towns or the prices of two cars.":"Comparen la población de dos pueblos o el precio de dos autos.",
"Round big numbers":"Redondear números grandes",
"About how many?":"¿Más o menos cuántos?",
"Round it.":"Redondéalo.",
"Find the two round numbers it sits between.":"Busca los dos números redondos entre los que está.",
"Look at the next digit to the right.":"Mira el dígito siguiente a la derecha.",
"{N} or more rounds up; {N} or less rounds down.":"{N} o más redondea hacia arriba; {N} o menos redondea hacia abajo.",
