"How many cubes are in one layer?":"¿Cuántos cubos hay en una capa?",
"Volume = length × width × height.":"Volumen = largo × ancho × altura.",
"Fill a small box with sugar cubes or blocks and count by layers.":"Llenen una cajita con cubos de azúcar o bloques y cuenten por capas.",
"A clue!":"¡Una pista!",
