"Counted tick marks, not jumps":"Contó marcas, no saltos",
"The bottom was multiplied.":"El número de abajo se multiplicó.",
"Do the same to the top.":"Haz lo mismo con el de arriba.",
"Adds the same number to the top and bottom of a fraction to make an equivalent one ({N}/{N} = {N}/{N}).":"Suma el mismo número arriba y abajo para hacer una fracción equivalente ({N}/{N} = {N}/{N}).",
